import"./style.css";import{Game}from"./game/Game.js";const app=document.querySelector("#app");app.innerHTML='\n  <main class="app-shell">\n    <section\n      class="screen start-screen"\n      id="start-screen"\n      aria-labelledby="start-title"\n    >\n      <img\n        class="start-label"\n        src="assets/images/label.png"\n        alt="Hoff"\n      />\n\n      <div class="bunting" aria-hidden="true">\n        <span></span><span></span><span></span><span></span>\n        <span></span><span></span><span></span><span></span>\n      </div>\n\n      <div class="start-content">\n\n        <div class="living-room" aria-hidden="true">\n          <img\n            class="room-furniture"\n            src="assets/images/furniture.png"\n            alt=""\n          />\n\n          <img\n            class="room-dog"\n            src="assets/images/dog.png"\n            alt=""\n          />\n\n          <img\n            class="room-balloons"\n            src="assets/images/baloons.png"\n            alt=""\n          />\n        </div>\n\n        <div class="start-card">\n          <h2>В честь дня рождения Hoff<br />дома шумно и весело!</h2>\n          <p>\n            Даже корги решил побаловаться и побегать по квартире, \n            ведь кто-то повсюду разбросал сахарные косточки. Помогите \n            пушистику собрать лакомства и получите <b>1000</b> бонусов на покупки \n            в Hoff.\n          </p>\n          <button\n            class="primary-button"\n            id="show-rules"\n            type="button"\n          >\n            Помочь корги\n          </button>\n        </div>\n\n        <p class="promotion-disclaimer">\n          Срок действия акции — с 15.04.2024 по 30.04.2024.\n          Подробная информация\n          <a href="#" class="promotion-disclaimer__link stub-link">\n            об условиях проведения акции.\n          </a>\n          Реклама. Рекламодатель — ООО «Домашний Интерьер».\n          ОГРН: 1077763747269.\n        </p>\n      </div>\n    </section>\n\n    <section\n      class="screen rules-screen"\n      id="rules-screen"\n      aria-labelledby="rules-title"\n      hidden\n    >\n      <img\n        class="rules-label"\n        src="assets/images/label.png"\n        alt="Hoff"\n      />\n\n      <div class="rules-balloons" aria-hidden="true">\n        <img\n          src="assets/images/many-balloons.png"\n          alt=""\n        />\n      </div>\n\n      <div class="rules-card">\n        <h2 class="rules-kicker" id="rules-title">\n          Правила игры\n        </h2>\n\n        <div class="rules-list">\n          <article class="rules-row">\n            <div class="rules-icon" aria-hidden="true">\n              <img\n                src="assets/images/yellow-bone.png"\n                alt=""\n              />\n            </div>\n\n            <div class="rules-copy">\n              <h3>Соберите лакомства</h3>\n              <p>\n                Пробегите 5 комнат и соберите 25 косточек.\n              </p>\n            </div>\n          </article>\n\n          <article class="rules-row">\n            <div class="rules-icon" aria-hidden="true">\n              <img\n                src="assets/images/button.png"\n                alt=""\n              />\n            </div>\n\n            <div class="rules-copy">\n              <h3>\n                <span class="rules-copy-desktop">\n                  Нажимайте на экран,\n                </span>\n\n                <span class="rules-copy-mobile">\n                  Нажимайте на кнопку «Прыжок»,\n                </span>\n              </h3>\n\n              <p>\n                чтобы перепрыгнуть препятствия или достать\n                до вкусняшки.\n              </p>\n            </div>\n          </article>\n\n          <article class="rules-row">\n            <div class="rules-icon" aria-hidden="true">\n              <img\n                src="assets/images/display.png"\n                alt=""\n              />\n            </div>\n\n            <div class="rules-copy">\n              <h3>Исследуйте всё</h3>\n              <p>\n                Прыгайте над небольшими предметами и залезайте\n                на крупные, например, стол или диван.\n              </p>\n            </div>\n          </article>\n        </div>\n\n        <div\n          class="rules-rewards"\n          aria-label="Награды за собранные косточки"\n        >\n          <article class="reward-card">\n            <div class="reward-image-wrapper">\n              <img\n                class="reward-image reward-image--single"\n                src="assets/images/bone.png"\n                alt=""\n              />\n            </div>\n\n            <h3 class="reward-title">\n              0-14 </br>косточек\n            </h3>\n\n            <p class="reward-description">\n              шанс переиграть\n            </p>\n          </article>\n\n          <article class="reward-card">\n            <div class="reward-image-wrapper">\n              <img\n                class="reward-image reward-image--many"\n                src="assets/images/bones.png"\n                alt=""\n              />\n            </div>\n\n            <h3 class="reward-title">\n              15-25  </br>косточек\n            </h3>\n\n            <p class="reward-description">\n              1000 бонусов в подарок,\n              и корги сыт!\n            </p>\n          </article>\n        </div>\n\n        <button\n          class="primary-button rules-start-button"\n          id="start-game"\n          type="button"\n        >\n          Играть\n        </button>\n      </div>\n    </section>\n\n    <section\n      class="screen play-screen"\n      id="play-screen"\n      aria-label="Игра «Супер Корги»"\n      hidden\n    >\n      <div class="game-frame">\n        <header class="game-header">\n          <img\n            class="game-logo"\n            src="assets/images/hoff-transparent.png"\n            alt="Hoff"\n          />\n\n          <div class="game-score" aria-live="polite">\n            <img\n              class="game-score-bone"\n              src="assets/images/yellow-bone.png"\n              alt=""\n              aria-hidden="true"\n            />\n            <span id="bone-counter">0 / 3</span>\n          </div>\n\n          <span class="game-header-spacer" aria-hidden="true"></span>\n        </header>\n\n        <div\n          class="game-stage"\n          id="game-stage"\n          aria-label="Игровое поле. Нажмите кнопку «Прыжок», чтобы прыгнуть."\n        >\n          <img\n            class="level-image"\n            src="assets/images/level.png"\n            alt=""\n            aria-hidden="true"\n          />\n\n          <div class="canvas-host" id="canvas-host"></div>\n\n          <img\n            class="game-dog"\n            src="assets/images/action-dog.gif"\n            alt=""\n            aria-hidden="true"\n          />\n        </div>\n\n        <div class="mobile-jump-control">\n          <button\n            class="mobile-jump-button"\n            id="jump-button"\n            type="button"\n            aria-label="Прыжок"\n          >\n            <img\n              src="assets/images/arrow.png"\n              alt=""\n              aria-hidden="true"\n            />\n            <span>Прыжок</span>\n          </button>\n        </div>\n        \n      </div>\n    </section>\n\n    <section\n      class="screen result-screen"\n      id="result-screen"\n      aria-labelledby="result-title"\n      hidden\n    >\n      <img\n        class="brand"\n        src="assets/images/label.png"\n        alt="Hoff"\n      />\n\n      <div class="bunting result-bunting" aria-hidden="true">\n        <span></span><span></span><span></span><span></span>\n        <span></span><span></span><span></span><span></span>\n      </div>\n\n      <div class="result-content">\n        <h2 id="result-title">Забирай бонусы, хозяин!</h2>\n\n        <p class="result-score">\n          <img\n            class="result-score-bone"\n            src="assets/images/finish-bone.svg"\n            alt=""\n            aria-hidden="true"\n          />\n          <span id="result-count">3 из 3</span>\n        </p>\n\n        <p class="result-description">\n          Отличная работа! Корги собрал все косточки.\n          Оставь свой email, чтобы узнать о бонусах.\n        </p>\n\n        <form id="bonus-form" class="bonus-form" novalidate>\n          <label class="visually-hidden" for="email">\n            Адрес электронной почты\n          </label>\n\n          <div class="email-field" id="email-field">\n            <input\n              id="email"\n              name="email"\n              type="email"\n              inputmode="email"\n              autocomplete="email"\n              placeholder="Введите email"\n              aria-describedby="email-error"\n              required\n            />\n            <span class="field-status" aria-hidden="true"></span>\n          </div>\n\n          <p\n            class="field-error"\n            id="email-error"\n            aria-live="polite"\n          ></p>\n\n          <label class="consent">\n            <input\n              id="consent"\n              name="consent"\n              type="checkbox"\n            />\n\n            <span class="consent-mark" aria-hidden="true">\n              <img\n                src="assets/images/check.svg"\n                alt=""\n              />\n            </span>\n\n            <span class="consent-text">\n              Соглашаюсь на получение рассылки и принимаю\n              <a href="#" class="stub-link">условия использования</a>\n              и\n              <a href="#" class="stub-link">политику конфиденциальности</a>.\n            </span>\n          </label>\n\n          <button\n            class="primary-button result-button"\n            id="submit-button"\n            type="submit"\n            disabled\n          >\n            Забрать бонусы\n          </button>\n        </form>\n\n        <p class="share-caption">Поделиться с друзьями:</p>\n\n        <div\n          class="social-placeholders"\n          aria-label="Поделиться в социальных сетях"\n        >\n          <a\n            class="social-link"\n            href="#"\n            aria-label="Поделиться во ВКонтакте"\n          >\n            <img\n              src="assets/images/vk.png"\n              alt="VK"\n            />\n          </a>\n\n          <a\n            class="social-link"\n            href="#"\n            aria-label="Поделиться в Одноклассниках"\n          >\n            <img\n              src="assets/images/ok.png"\n              alt="OK"\n            />\n          </a>\n\n          <a\n            class="social-link"\n            href="#"\n            aria-label="Поделиться в Telegram"\n          >\n            <img\n              src="assets/images/tg.png"\n              alt="Telegram"\n            />\n          </a>\n\n          <a\n            class="social-link"\n            href="#"\n            aria-label="Поделиться в Viber"\n          >\n            <img\n              src="assets/images/viber.png"\n              alt="Viber"\n            />\n          </a>\n\n          <a\n            class="social-link"\n            href="#"\n            aria-label="Поделиться в WhatsApp"\n          >\n            <img\n              src="assets/images/whatsapp.png"\n              alt="WhatsApp"\n            />\n          </a>\n        </div>\n      </div>\n    </section>\n  </main>\n';const screens={start:document.querySelector("#start-screen"),rules:document.querySelector("#rules-screen"),play:document.querySelector("#play-screen"),result:document.querySelector("#result-screen")};let game=null;function showScreen(n){for(const[e,s]of Object.entries(screens))s.hidden=e!==n;window.scrollTo(0,0)}document.querySelector("#show-rules").addEventListener("click",(()=>showScreen("rules"))),document.querySelector("#start-game").addEventListener("click",(()=>{showScreen("play"),requestAnimationFrame((()=>{game?.destroy();const n=document.querySelector("#bone-counter");game=new Game({container:document.querySelector("#canvas-host"),inputArea:document.querySelector("#game-stage"),jumpButton:document.querySelector("#jump-button"),counter:n,pauseButton:document.querySelector("#pause-button"),onComplete:n=>{document.querySelector("#result-count").textContent=`${n} из 3`,game?.destroy(),game=null,showScreen("result")}})}))}));const form=document.querySelector("#bonus-form"),email=document.querySelector("#email"),field=document.querySelector("#email-field"),error=document.querySelector("#email-error"),consent=document.querySelector("#consent"),submitButton=document.querySelector("#submit-button");let emailTouched=!1;function getEmailState(){return email.value.trim()?email.validity.valid?{valid:!0,message:""}:{valid:!1,message:"Проверьте правильность введенных данных."}:{valid:!1,message:"Введите адрес электронной почты."}}function updateForm(){const n=getEmailState(),e=email.value.trim().length>0;field.classList.toggle("is-valid",e&&n.valid),field.classList.toggle("is-invalid",emailTouched&&!n.valid),email.setAttribute("aria-invalid",String(emailTouched&&!n.valid)),error.textContent=emailTouched&&!n.valid?n.message:"",submitButton.disabled=!(n.valid&&consent.checked)}email.addEventListener("input",updateForm),email.addEventListener("blur",(()=>{emailTouched=!0,updateForm()})),consent.addEventListener("change",updateForm),form.addEventListener("submit",(n=>{n.preventDefault(),emailTouched=!0,updateForm(),submitButton.disabled&&email.focus()})),document.querySelectorAll(".stub-link").forEach((n=>{n.addEventListener("click",(n=>n.preventDefault()))})),import.meta.hot&&import.meta.hot.dispose((()=>{game?.destroy()}));